// --- Issue #1: brick bounces ----------------------------------------------
// Each case from ISSUES.md #1 gets a red test first: per-face bounce,
// corner, push-out, neighbours (exactly-once), tunnelling.

// Helper: a pristine level-1 state with every brick except `keep` removed,
// so a test can aim at a single brick.
function stateWithOnly(state, keep) {
  for (const b of state.bricks) if (b !== keep) b.alive = false;
  return state;
}

test('#1 bottom face: vy flips, vx untouched, ball pushed below', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  stateWithOnly(state, brick);
  const vx = 120;
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + brick.h + 10, r: 7, vx, vy: -ballSpeed(1) };
  step(state, 1 / 60);
  assert.ok(state.ball.vy > 0, 'vy should flip from up to down');
  assert.equal(state.ball.vx, vx, 'vx must be left exactly as it was');
  assert.ok(
    state.ball.y - state.ball.r >= brick.y + brick.h,
    'ball must be pushed out below the brick'
  );
  assert.equal(brick.alive, false);
});

test('#1 side face: vx flips, vy untouched, ball pushed sideways', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  stateWithOnly(state, brick);
  const vy = -90;
  state.ball = { x: brick.x - 10, y: brick.y + brick.h / 2, r: 7, vx: ballSpeed(1), vy };
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0, 'vx should flip from right to left');
  assert.equal(state.ball.vy, vy, 'vy must be left exactly as it was');
  assert.ok(state.ball.x + state.ball.r <= brick.x, 'ball must be pushed out left of the brick');
  assert.equal(brick.alive, false);
});

test('#1 corner: equal penetrations flip both axes', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball centre 3 px out on x and 3 px out on y of the brick's bottom-left
  // corner => identical horizontal and vertical penetration (r = 7).
  const ball = { x: brick.x - 3, y: brick.y + brick.h + 3, r: 7, vx: 200, vy: -200 };
  const hits = resolveBricks(ball, state.bricks);
  assert.deepEqual(hits, [brick]);
  assert.equal(ball.vx, -200, 'diagonal hit flips vx');
  assert.equal(ball.vy, 200, 'diagonal hit flips vy');
  assert.ok(ball.x + ball.r <= brick.x, 'pushed out on the left');
  assert.ok(ball.y - ball.r >= brick.y + brick.h, 'pushed out below');
});

test('#1 neighbours: a seam overlapping two bricks bounces exactly once', () => {
  const state = createState(1);
  const [b0, b1] = state.bricks; // two adjacent bricks in row 0, gap 8 px
  const seamX = (b0.x + b0.w + b1.x) / 2; // centre of the 8 px gap
  const ball = { x: seamX, y: b0.y + b0.h + 5, r: 7, vx: 0, vy: -250 };
  const hits = resolveBricks(ball, state.bricks);
  assert.equal(hits.length, 2, 'both neighbours are hit in the same pass');
  assert.equal(b0.alive, false);
  assert.equal(b1.alive, false);
  assert.equal(ball.vy, 250, 'vy flipped exactly once, not twice');
  assert.equal(ball.vx, 0, 'vx untouched on a straight-up seam hit');
});

test('#1 push-out: a resolved bounce leaves the ball clear of the brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  stateWithOnly(state, brick);
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + brick.h + 2, r: 7, vx: 0, vy: -ballSpeed(1) };
  step(state, 1 / 60);
  assert.ok(
    !collides(state.ball, brick),
    'after the bounce the ball must not overlap the brick it hit'
  );
});

test('#1 tunnelling: level-6 speed cannot jump over a brick in one frame', () => {
  const state = createState(6);
  const brick = state.bricks[0];
  stateWithOnly(state, brick);
  const speed = ballSpeed(6); // 710 px/s
  // One 50 ms frame moves the ball 35.5 px: more than the 34 px needed to
  // cross the brick. Without a sweep it would skip right over it.
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + brick.r + 0.5,
    r: 7,
    vx: 0,
    vy: -speed,
  };
  step(state, 0.05);
  assert.equal(brick.alive, false, 'the brick must be hit, not jumped over');
  assert.ok(state.ball.vy > 0, 'the ball must have bounced back down');
});

test('#1 integration: a hit breaks the brick and scores a combo', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  stateWithOnly(state, brick);
  const scoreBefore = state.score;
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + brick.h + 8, r: 7, vx: 0, vy: -ballSpeed(1) };
  step(state, 1 / 60);
  assert.equal(brick.alive, false);
  assert.equal(state.combo, 1);
  assert.ok(state.score > scoreBefore, 'score increases when a brick breaks');
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

