// Ball speed as a function of the level (ramps up with each level).
export function ballSpeed(level = 1) {
  return 260 + (level - 1) * 90;
}

// Longest single move we allow before re-checking collisions (seconds of
// motion at the current velocity). Bounded by the paddle band (12 px) so the
// ball's bottom edge cannot skip over the paddle, and far smaller than the
// 34 px (BRICK_H + 2*BALL_R) needed to cross a brick: tunnelling is
// impossible at any level.
const MAX_SUBSTEP = PADDLE_H;

