// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks.
//
// The move is split into substeps of at most MAX_SUBSTEP so that a fast ball
// (up to 35.5 px per capped frame at level 6) cannot skip over a brick or the
// paddle between two discrete checks (tunnelling, issue #1). Walls use edge
// tests, so they stay safe at any substep size.
//
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle, bricks } = state;

  const distance = Math.hypot(ball.vx, ball.vy) * dt;
  const substeps = Math.max(1, Math.ceil(distance / MAX_SUBSTEP));
  const h = dt / substeps;

  for (let i = 0; i < substeps; i++) {
    ball.x += ball.vx * h;
    ball.y += ball.vy * h;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks: one bounce per substep, exactly once even on a seam.
    const hits = resolveBricks(ball, bricks);
    for (const brick of hits) {
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }

    // Exit through the bottom: ball lost
    if (ball.y - ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}

