    state.paddle.x = Math.max(0, Math.min(WIDTH - PADDLE_W, state.paddle.x + (Math.sin(f / 37) * 40)));
    const lost = step(state, 0.0167);
    if (lost) { state.ball = createState(state.level).ball; state.lives = 9; }
    if (state.bricks.every(b => !b.alive)) { state.level++; state.bricks = createState(state.level).bricks; }
    frame(ctx, state);
    const alive = state.bricks.filter(b => b.alive).length;
    broken += lastBricks - alive; lastBricks = alive;
